// Validation et préparation des données (avec support batch)
// v2.1 - 2026-05-01: Ajout normalizeTraite() pour UPDATE cd.traite
const input = $input.first().json;
const body = input.body || input;
const headers = input.headers || {};
const projectId = headers['x-project-id'] || body.project_id || body.projectId || (body.context && body.context.project_id) || null;

const startTime = Date.now();

// ============================================
// NORMALISATION TRAITE (UPDATE cd.traite 2026-05-01)
// 7 patterns couvrant ~95% des cas
// Ref: docs/issues/2026-05-01-update-cd-traite-normalization.md
// À SUPPRIMER quand PR feat(vocalization) Option C sera mergée côté API
// ============================================
function normalizeTraite(input) {
  if (!input) return input;
  let m;
  // Pattern 1: "English Explanation of <X>" → "<X>"
  m = input.match(/^English Explanation of (.+)$/);
  if (m) return m[1];
  // Pattern 2: "Rif <X>" → "<X>"
  m = input.match(/^Rif (.+)$/);
  if (m) return m[1];
  // Pattern 3: "<X>; Alternate Version|Mahadurah Tanina|Second Recension" → "<X>"
  m = input.match(/^(.+); (?:Alternate Version|Mahadurah Tanina|Second Recension)$/);
  if (m) return m[1];
  // Pattern 4: "Mishnah Taanit" → "Mishnah Ta'anit"
  if (input === 'Mishnah Taanit') return "Mishnah Ta'anit";
  // Pattern 5: "Avot" → "Pirkei Avot"
  if (input === 'Avot') return 'Pirkei Avot';
  // Pattern 6: "Mishnah Baba <X>" → "Mishnah Bava <X>"
  m = input.match(/^Mishnah Baba (.+)$/);
  if (m) return `Mishnah Bava ${m[1]}`;
  // Pattern 7: "Jerusalem Talmud, <X>" → "Jerusalem Talmud <X>"
  m = input.match(/^Jerusalem Talmud, (.+)$/);
  if (m) return `Jerusalem Talmud ${m[1]}`;
  // Default: pass-through (déjà canonique)
  return input;
}

// Extraction des paramètres
const openaiApiKey = body.openai_api_key || '';
const context = body.context || {};

// Normaliser traite si présent dans le contexte
const normalizedTraite = context.traite ? normalizeTraite(context.traite) : null;
const traiteWasNormalized = normalizedTraite && normalizedTraite !== context.traite;

// Détecter mode batch ou single
const isBatch = Array.isArray(body.items) && body.items.length > 0;

// Validation
const errors = [];

if (!openaiApiKey || openaiApiKey.trim().length === 0) {
  errors.push('Le champ "openai_api_key" est requis');
}

if (isBatch) {
  // Validation batch
  for (let i = 0; i < body.items.length; i++) {
    const item = body.items[i];
    if (!item.text || item.text.trim().length === 0) {
      errors.push(`Item ${i}: le champ "text" est requis`);
    }
  }
} else {
  // Validation single (existant)
  const text = body.text || '';
  if (!text || text.trim().length === 0) {
    errors.push('Le champ "text" est requis');
  }
}

// === MODE SINGLE (rétrocompatibilité) ===
if (!isBatch) {
  const text = body.text || '';
  const segmentId = body.segment_id || null;
  const sourceTextId = body.source_text_id || null;
  const commentaryId = body.commentary_id || null;

  let cacheSearchParams = '';
  if (segmentId) {
    cacheSearchParams = `segment_id=${segmentId}`;
  } else if (sourceTextId) {
    cacheSearchParams = `source_text_id=${sourceTextId}`;
  } else if (commentaryId) {
    cacheSearchParams = `commentary_id=${commentaryId}`;
  } else if (normalizedTraite && context.page) {
    // Utiliser le traite normalisé pour la recherche cache
    cacheSearchParams = `traite=${encodeURIComponent(normalizedTraite)}&page=${encodeURIComponent(context.page)}`;
    if (context.commentator) {
      cacheSearchParams += `&commentator=${encodeURIComponent(context.commentator)}`;
    }
  }

  return [{
    json: {
      valid: errors.length === 0,
      errors: errors,
      isBatch: false,
      text: text,
      openaiApiKey: openaiApiKey,
      segmentId: segmentId,
      sourceTextId: sourceTextId,
      commentaryId: commentaryId,
      context: context,
      normalizedTraite: normalizedTraite,
      traiteWasNormalized: traiteWasNormalized,
      startTime: startTime,
      cacheSearchParams: cacheSearchParams,
      canSearchCache: !!(segmentId || sourceTextId || commentaryId || (normalizedTraite && context.page)),
      isCommentary: !!commentaryId
    }
  }];
}

// === MODE BATCH ===
const items = body.items.map((item, index) => ({
  index,
  text: item.text,
  segment_id: item.segment_id || null,
  commentary_id: item.commentary_id || null,
  source_text_id: item.source_text_id || null
}));

return [{
  json: {
    valid: errors.length === 0,
    errors: errors,
    isBatch: true,
    items: items,
    itemCount: items.length,
    openaiApiKey: openaiApiKey,
    context: context,
    normalizedTraite: normalizedTraite,
    traiteWasNormalized: traiteWasNormalized,
    startTime: startTime,
    projectId: projectId
  }
}];

// Construire la réponse d'erreur de validation
const input = $input.first().json;

return [{
  json: {
    success: false,
    error: {
      code: 400,
      message: input.errors.join(', '),
      status: 'BAD_REQUEST'
    }
  }
}];
